properties.query:
let windowSize = 45m;
let fsParams = dynamic(["FS_THR_ENABLE","FS_GCS_ENABLE","FS_EKF_ACTION","FS_CRASH_CHECK"]);
let cpuMax = toscalar(
    _GetWatchlist('UAV_Threshold_List')
    | where ThresholdKey == 'MaxCpuUsagePct'
    | project toreal(Value));
// S19: Failsafe 파라미터 비활성화
let S19 =
    UAVConfigAudit_CL
    | where TimeGenerated > ago(windowSize)
    | where ParamId in (fsParams)
    | where toreal(ParamValueAfter) == 0
    | project T1=TimeGenerated, UAVId=tostring(UAVId), ParamId;
// S18: MAVLink 서명실패 (중간자)
let S18 =
    UAVMavsec_CL
    | where TimeGenerated > ago(windowSize)
    | where FailedCount > 0
    | project T2=TimeGenerated, UAVId=tostring(UAVId);
// S25: 컨테이너 자원고갈 DoS
let S25 =
    UAVResourceMetrics_CL
    | where TimeGenerated > ago(windowSize)
    | where CpuUsagePct > cpuMax
    | where ContainerName contains "mavlink"
    | summarize T3=min(TimeGenerated) by ContainerName;
S19
| join kind=inner (S18) on UAVId
| where T2 >= T1 and T2 <= T1 + 15m
| join kind=inner (S25)
    on $left.T2 <= $right.T3 and $right.T3 <= ($left.T2 + 10m)
| extend CampaignType = "C5_Failsafe무력화_MAVLink중간자_DoS_RTL없음"
| extend StepSummary = strcat("S19@", tostring(T1), "(", ParamId, "=0) → S18@", tostring(T2), " → S25@", tostring(T3))
| extend Severity = "High"
| project T1, T2, T3, UAVId, ParamId, ContainerName, CampaignType, StepSummary, Severity
